<?php
namespace Slind\ContactForm\Admin;

use Slind\ContactForm\PostTypes\Registrar;
use Slind\ContactForm\Support\FieldParser;

defined( 'ABSPATH' ) || exit;

final class FormEditor {
	public static function register_hooks() {
		add_action( 'add_meta_boxes', array( __CLASS__, 'boxes' ) );
		add_action( 'save_post_' . Registrar::FORM, array( __CLASS__, 'save_form' ) );
		add_action( 'save_post_' . Registrar::ENTRY, array( __CLASS__, 'save_entry' ) );
		add_action( 'admin_enqueue_scripts', array( __CLASS__, 'assets' ) );
	}
	public static function boxes() {
		add_meta_box( 'slind_form_builder', __( 'Form Builder', 'slind-contact-form' ), array( __CLASS__, 'builder' ), Registrar::FORM, 'normal', 'high' );
		add_meta_box( 'slind_form_delivery', __( 'Delivery & Messages', 'slind-contact-form' ), array( __CLASS__, 'delivery' ), Registrar::FORM, 'normal' );
		add_meta_box( 'slind_entry_data', __( 'Entry Details', 'slind-contact-form' ), array( __CLASS__, 'entry' ), Registrar::ENTRY, 'normal', 'high' );
	}
	public static function assets( $hook ) {
		$screen = get_current_screen(); if ( ! $screen || Registrar::FORM !== $screen->post_type || ! in_array( $hook, array( 'post.php', 'post-new.php' ), true ) ) { return; }
		wp_enqueue_script( 'jquery-ui-sortable' );
		wp_enqueue_script( 'slind-form-builder', SLIND_CONTACT_FORM_URL . 'assets/js/form-builder.js', array( 'jquery', 'jquery-ui-sortable' ), SLIND_CONTACT_FORM_VERSION, true );
		wp_enqueue_style( 'slind-form-builder', SLIND_CONTACT_FORM_URL . 'assets/css/form-builder.css', array(), SLIND_CONTACT_FORM_VERSION );
		wp_localize_script( 'slind-form-builder', 'slindFormBuilder', array( 'confirmDelete' => __( 'Delete this field?', 'slind-contact-form' ), 'types' => array_fill_keys( FieldParser::TYPES, true ) ) );
	}
	public static function builder( $post ) {
		wp_nonce_field( 'slind_save_form', 'slind_form_nonce' ); $fields = FieldParser::get( $post->ID );
		?><p><?php esc_html_e( 'Add fields, drag them into order, then configure each field below.', 'slind-contact-form' ); ?></p><div class="slind-builder__palette"><?php foreach ( FieldParser::TYPES as $type ) : ?><button type="button" class="button slind-builder__add" data-type="<?php echo esc_attr( $type ); ?>">+ <?php echo esc_html( ucwords( str_replace( array( '_', 'checkboxes' ), array( ' ', 'checkbox group' ), $type ) ) ); ?></button><?php endforeach; ?></div><div id="slind-builder-fields" class="slind-builder__fields"></div><input type="hidden" id="slind-fields-json" name="slind_fields_json" value="<?php echo esc_attr( wp_json_encode( $fields ) ); ?>"><script type="text/html" id="tmpl-slind-field"><?php self::field_template(); ?></script><?php if ( $post->ID ) : ?><p><strong><?php esc_html_e( 'Shortcode:', 'slind-contact-form' ); ?></strong> <code>[slind_form id="<?php echo esc_attr( $post->ID ); ?>"]</code></p><?php endif;
	}
	private static function field_template() {
		?><article class="slind-builder__field"><header><span class="dashicons dashicons-move" aria-hidden="true"></span><strong data-field-title></strong><span class="slind-builder__badge"><?php esc_html_e( 'Structural', 'slind-contact-form' ); ?></span><span class="slind-builder__actions"><button type="button" class="button-link slind-builder__duplicate"><?php esc_html_e( 'Duplicate', 'slind-contact-form' ); ?></button><button type="button" class="button-link-delete slind-builder__delete"><?php esc_html_e( 'Delete', 'slind-contact-form' ); ?></button></span></header><div class="slind-builder__settings"><label><?php esc_html_e( 'Type', 'slind-contact-form' ); ?><select data-key="type"><?php foreach ( FieldParser::TYPES as $type ) : ?><option value="<?php echo esc_attr( $type ); ?>"><?php echo esc_html( ucwords( str_replace( '_', ' ', $type ) ) ); ?></option><?php endforeach; ?></select></label><label class="slind-builder__setting--label"><span data-label-text><?php esc_html_e( 'Field label', 'slind-contact-form' ); ?></span><input type="text" data-key="label"></label><label class="slind-builder__setting--name"><span data-name-text><?php esc_html_e( 'Field key', 'slind-contact-form' ); ?></span><input type="text" data-key="name" pattern="[a-z0-9_-]+"></label><label class="slind-builder__setting--placeholder"><?php esc_html_e( 'Placeholder', 'slind-contact-form' ); ?><input type="text" data-key="placeholder"></label><label class="slind-builder__setting--default"><?php esc_html_e( 'Default value', 'slind-contact-form' ); ?><input type="text" data-key="default"></label><label><?php esc_html_e( 'CSS class', 'slind-contact-form' ); ?><input type="text" data-key="class"></label><label class="slind-builder__wide slind-builder__setting--help"><span data-help-text><?php esc_html_e( 'Help text', 'slind-contact-form' ); ?></span><input type="text" data-key="help"></label><label class="slind-builder__wide slind-builder__options"><?php esc_html_e( 'Options (one per line)', 'slind-contact-form' ); ?><textarea rows="4" data-key="options"></textarea></label><label class="slind-builder__required"><input type="checkbox" data-key="required"> <?php esc_html_e( 'Required', 'slind-contact-form' ); ?></label></div></article><?php
	}
	public static function delivery( $post ) {
		$fields = FieldParser::get( $post->ID ); $reply = get_post_meta( $post->ID, '_slind_reply_to', true ); $user_field = get_post_meta( $post->ID, '_slind_user_email_field', true );
		?><h3><?php esc_html_e( 'Admin Notification', 'slind-contact-form' ); ?></h3><p><label><strong><?php esc_html_e( 'Recipient email', 'slind-contact-form' ); ?></strong><br><input class="widefat" type="email" name="slind_recipient" value="<?php echo esc_attr( get_post_meta( $post->ID, '_slind_recipient', true ) ); ?>" placeholder="<?php echo esc_attr( get_option( 'admin_email' ) ); ?>"></label></p><p><label><strong><?php esc_html_e( 'Subject', 'slind-contact-form' ); ?></strong><br><input class="widefat" type="text" name="slind_subject" value="<?php echo esc_attr( get_post_meta( $post->ID, '_slind_subject', true ) ); ?>" placeholder="New form submission: {form_title}"></label></p><p><label><strong><?php esc_html_e( 'Intro/message copy', 'slind-contact-form' ); ?></strong><br><textarea class="widefat" rows="4" name="slind_admin_message" placeholder="A new form submission has been received."><?php echo esc_textarea( get_post_meta( $post->ID, '_slind_admin_message', true ) ); ?></textarea></label></p><p><label><strong><?php esc_html_e( 'Reply-to email field', 'slind-contact-form' ); ?></strong><br><?php self::email_field_select( 'slind_reply_to', $fields, $reply, __( 'First email field', 'slind-contact-form' ) ); ?></label></p><hr><h3><?php esc_html_e( 'User Notification', 'slind-contact-form' ); ?></h3><p><label><input type="checkbox" name="slind_user_notification_enabled" value="1"<?php checked( get_post_meta( $post->ID, '_slind_user_notification_enabled', true ), '1' ); ?>> <strong><?php esc_html_e( 'Send a confirmation email to the person submitting this form', 'slind-contact-form' ); ?></strong></label></p><p><label><strong><?php esc_html_e( 'Notification email field', 'slind-contact-form' ); ?></strong><br><?php self::email_field_select( 'slind_user_email_field', $fields, $user_field, __( 'Reply-to field or first email field', 'slind-contact-form' ) ); ?></label></p><p><label><strong><?php esc_html_e( 'Subject', 'slind-contact-form' ); ?></strong><br><input class="widefat" type="text" name="slind_user_subject" value="<?php echo esc_attr( get_post_meta( $post->ID, '_slind_user_subject', true ) ); ?>" placeholder="<?php esc_attr_e( 'Thank you — we received your message', 'slind-contact-form' ); ?>"></label></p><p><label><strong><?php esc_html_e( 'Email message', 'slind-contact-form' ); ?></strong><br><textarea class="widefat" rows="6" name="slind_user_message" placeholder="<?php esc_attr_e( "Thank you!\n\nWe've received your message and will be in touch soon.", 'slind-contact-form' ); ?>"><?php echo esc_textarea( get_post_meta( $post->ID, '_slind_user_message', true ) ); ?></textarea></label></p><hr><h3><?php esc_html_e( 'Form Response', 'slind-contact-form' ); ?></h3><p><label><strong><?php esc_html_e( 'Submit button text', 'slind-contact-form' ); ?></strong><br><input class="widefat" type="text" name="slind_submit_label" value="<?php echo esc_attr( get_post_meta( $post->ID, '_slind_submit_label', true ) ); ?>" placeholder="Submit"></label></p><p><label><strong><?php esc_html_e( 'Success message', 'slind-contact-form' ); ?></strong><br><textarea class="widefat" rows="3" name="slind_success" placeholder="Thank you. Your submission has been received."><?php echo esc_textarea( get_post_meta( $post->ID, '_slind_success', true ) ); ?></textarea></label></p><?php
	}
	private static function email_field_select( $name, $fields, $selected, $empty_label ) {
		echo '<select class="widefat" name="' . esc_attr( $name ) . '"><option value="">' . esc_html( $empty_label ) . '</option>'; foreach ( $fields as $field ) { if ( 'email' === $field['type'] ) { printf( '<option value="%1$s"%2$s>%3$s</option>', esc_attr( $field['name'] ), selected( $selected, $field['name'], false ), esc_html( $field['label'] ) ); } } echo '</select>';
	}
	public static function entry( $post ) {
		$status = get_post_meta( $post->ID, '_slind_entry_status', true ) ?: 'new';
		if ( 'new' === $status ) { $status = 'read'; update_post_meta( $post->ID, '_slind_entry_status', 'read' ); }
		wp_nonce_field( 'slind_save_entry', 'slind_entry_nonce' ); $form_id = absint( get_post_meta( $post->ID, '_slind_form_id', true ) ); $admin_delivery = get_post_meta( $post->ID, '_slind_admin_delivery_status', true ) ?: get_post_meta( $post->ID, '_slind_delivery_status', true ); $admin_message = get_post_meta( $post->ID, '_slind_admin_delivery_message', true ) ?: get_post_meta( $post->ID, '_slind_delivery_message', true ); $user_delivery = get_post_meta( $post->ID, '_slind_user_delivery_status', true ) ?: 'not-recorded'; $user_message = get_post_meta( $post->ID, '_slind_user_delivery_message', true ); $labels = (array) get_post_meta( $post->ID, '_slind_labels', true );
		echo '<p><strong>' . esc_html__( 'Form:', 'slind-contact-form' ) . '</strong> ' . esc_html( get_the_title( $form_id ) ) . '</p><p><strong>' . esc_html__( 'Submitted:', 'slind-contact-form' ) . '</strong> ' . esc_html( get_the_date( '', $post ) . ' ' . get_the_time( '', $post ) ) . '</p><p><label><strong>' . esc_html__( 'Entry status:', 'slind-contact-form' ) . '</strong> <select name="slind_entry_status">';
		foreach ( array( 'new' => __( 'New', 'slind-contact-form' ), 'read' => __( 'Read', 'slind-contact-form' ), 'archived' => __( 'Archived', 'slind-contact-form' ) ) as $key => $label ) { printf( '<option value="%1$s"%2$s>%3$s</option>', esc_attr( $key ), selected( $status, $key, false ), esc_html( $label ) ); } echo '</select></label></p><p><strong>' . esc_html__( 'Admin notification:', 'slind-contact-form' ) . '</strong> ' . esc_html( $admin_delivery ?: 'unknown' ) . ( $admin_message ? ' — ' . esc_html( $admin_message ) : '' ) . '</p><p><strong>' . esc_html__( 'User notification:', 'slind-contact-form' ) . '</strong> ' . esc_html( $user_delivery ) . ( $user_message ? ' — ' . esc_html( $user_message ) : '' ) . '</p><table class="widefat striped"><tbody>';
		$payload = (array) get_post_meta( $post->ID, '_slind_payload', true ); $fields = get_post_meta( $post->ID, '_slind_fields_snapshot', true ); $fields = is_array( $fields ) && $fields ? $fields : FieldParser::get( $form_id ); self::entry_rows( $fields, $payload, $labels ); echo '</tbody></table>';
	}
	private static function entry_rows( $fields, $payload, $labels ) {
		$rendered = array();
		foreach ( $fields as $field ) {
			if ( 'section' === $field['type'] ) { echo '<tr><th colspan="2" style="background:#f0f0f1;padding-top:16px"><strong>' . esc_html( $field['label'] ) . '</strong>' . ( $field['help'] ? '<br><span style="font-weight:normal">' . esc_html( $field['help'] ) . '</span>' : '' ) . '</th></tr>'; continue; }
			$key = $field['name']; if ( ! array_key_exists( $key, $payload ) ) { continue; } $rendered[ $key ] = true; $value = $payload[ $key ]; echo '<tr><th style="width:25%">' . esc_html( isset( $labels[ $key ] ) ? $labels[ $key ] : $field['label'] ) . '</th><td>' . nl2br( esc_html( is_array( $value ) ? implode( ', ', $value ) : $value ) ) . '</td></tr>';
		}
		foreach ( $payload as $key => $value ) { if ( isset( $rendered[ $key ] ) ) { continue; } echo '<tr><th style="width:25%">' . esc_html( isset( $labels[ $key ] ) ? $labels[ $key ] : ucwords( str_replace( '_', ' ', $key ) ) ) . '</th><td>' . nl2br( esc_html( is_array( $value ) ? implode( ', ', $value ) : $value ) ) . '</td></tr>'; }
	}
	public static function save_form( $post_id ) {
		if ( ! isset( $_POST['slind_form_nonce'] ) || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['slind_form_nonce'] ) ), 'slind_save_form' ) || ! current_user_can( Registrar::MANAGE_CAP ) || wp_is_post_autosave( $post_id ) ) { return; }
		$json = isset( $_POST['slind_fields_json'] ) ? json_decode( wp_unslash( $_POST['slind_fields_json'] ), true ) : array(); update_post_meta( $post_id, '_slind_fields_v2', FieldParser::sanitize_fields( is_array( $json ) ? $json : array() ) );
		foreach ( array( 'recipient' => 'sanitize_email', 'subject' => 'sanitize_text_field', 'admin_message' => 'sanitize_textarea_field', 'reply_to' => 'sanitize_key', 'user_email_field' => 'sanitize_key', 'user_subject' => 'sanitize_text_field', 'user_message' => 'sanitize_textarea_field', 'submit_label' => 'sanitize_text_field', 'success' => 'sanitize_textarea_field' ) as $key => $callback ) { update_post_meta( $post_id, '_slind_' . $key, isset( $_POST[ 'slind_' . $key ] ) ? call_user_func( $callback, wp_unslash( $_POST[ 'slind_' . $key ] ) ) : '' ); }
		update_post_meta( $post_id, '_slind_user_notification_enabled', isset( $_POST['slind_user_notification_enabled'] ) ? '1' : '0' );
	}
	public static function save_entry( $post_id ) {
		if ( ! isset( $_POST['slind_entry_nonce'] ) || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['slind_entry_nonce'] ) ), 'slind_save_entry' ) || ! current_user_can( Registrar::MANAGE_CAP ) ) { return; }
		$status = isset( $_POST['slind_entry_status'] ) ? sanitize_key( $_POST['slind_entry_status'] ) : 'read'; if ( in_array( $status, array( 'new', 'read', 'archived' ), true ) ) { update_post_meta( $post_id, '_slind_entry_status', $status ); }
	}
}
